// Widget templates (W-23): ChatKit Studio's gallery (https://widgets.chatkit.studio/gallery, fetched
// 2026-10-11), each as the .widget file Studio's Download makes: its JSX-like view run through Studio's
// own converter (/convert-widget-to-file) into the Jinja template, its example data as `sample`
// (Studio's demo image paths pointed at widgets.chatkit.studio), and its zod Schema as `jsonSchema`
// (W-30: converted with zod's toJSONSchema, as Studio's download does). Names and descriptions are ours.
// OpenAI's examples; the gallery states no licence: check before launch, like the agent guide (D-52).
// Loaded only when the Templates tab opens.

export interface WidgetTemplate {
  id: string;
  name: string;
  description: string;
  /** The whole .widget file. */
  file: string;
}

